import Foundation
import HTTPTypes
import OpenAPIRuntime
import Testing

@testable import PlayerzAPI

/// Real v1 responses for a league's match times and the entry fee
/// (playerz-ios#23), decoded through the generated client.
///
/// Captured from the server's routes on the perf database, ranking on: a
/// singles league of four drawn with weekly deadlines; the player proposing a
/// court and a time (refused first at the club's booking limit), answering
/// their own proposal refused, the other side seeing it and accepting; a
/// proposal taken back, then again; and the fee's page asked for an entry
/// paid at the club.
@Suite("Match times decode the server's JSON")
struct MatchTimesDecodingTests {
    private func client(_ replies: [String: (Int, String)]) -> Client {
        Playerz.client(baseURL: URL(string: "https://playerz.test/api/v1")!, transport: Canned(replies: replies))
    }

    private func myMatch(_ draw: Components.Schemas.Draw, _ id: String) throws -> Components.Schemas.DrawMatch {
        try #require(draw.groups.flatMap(\.matches).first { $0.id == id })
    }

    @Test func aLeagueWithDeadlines() async throws {
        let draw = try await client(["getTournamentDraw": (200, LEAGUE)]).getTournamentDraw(path: .init(id: "t")).ok.body.json.data
        #expect(draw.format == "LEAGUE" && draw.status == .IN_PROGRESS)
        let mine = draw.groups.flatMap(\.matches).filter { $0.mine }
        #expect(mine.count == 3)
        #expect(mine.allSatisfy { $0.status == .READY && $0.deadline != nil && $0.mySide != nil && $0.proposal == nil })
    }

    @Test func proposingThenTheOtherSideAccepts() async throws {
        let request = Components.Schemas.ProposeMatchRequest(resourceId: "r", startTs: .now, durationMinutes: 60)
        let limit = try await client(["proposeMatchTime": (409, LIMIT)]).proposeMatchTime(path: .init(id: "m"), body: .json(request))
        #expect(try limit.conflict.body.json.error.code == "BOOKING_LIMIT_REACHED")
        let proposed = try await client(["proposeMatchTime": (201, PROPOSED)])
            .proposeMatchTime(path: .init(id: "m"), body: .json(request)).created.body.json.data
        let ours = try #require(proposed.groups.flatMap(\.matches).first { $0.proposal != nil })
        let proposal = try #require(ours.proposal)
        #expect(proposal.side == ours.mySide)
        #expect(proposal.until > .now && proposal.priceCents > 0)
        let own = try await client(["acceptMatchTime": (409, OWN)]).acceptMatchTime(path: .init(id: "m"))
        #expect(try own.conflict.body.json.error.code == "TOURNAMENT_NO_PROPOSAL")
        let theirs = try await client(["getTournamentDraw": (200, THEIRS)]).getTournamentDraw(path: .init(id: "t")).ok.body.json.data
        let toAnswer = try myMatch(theirs, ours.id)
        #expect(toAnswer.proposal != nil && toAnswer.proposal?.side != toAnswer.mySide)
        let accepted = try await client(["acceptMatchTime": (200, ACCEPTED)]).acceptMatchTime(path: .init(id: "m")).ok.body.json.data
        let placed = try myMatch(accepted, ours.id)
        #expect(placed.scheduled != nil && placed.proposal == nil)
    }

    @Test func takingAProposalBack() async throws {
        let back = try await client(["letGoMatchTime": (200, LET_GO)]).letGoMatchTime(path: .init(id: "m")).ok.body.json.data
        #expect(back.groups.flatMap(\.matches).filter { $0.mine && $0.proposal != nil }.isEmpty)
        let again = try await client(["letGoMatchTime": (409, NO_PROPOSAL)]).letGoMatchTime(path: .init(id: "m"))
        #expect(try again.conflict.body.json.error.code == "TOURNAMENT_NO_PROPOSAL")
    }

    @Test func noFeeToPayAtTheClub() async throws {
        let response = try await client(["openTournamentEntryCheckout": (409, NOT_DUE)])
            .openTournamentEntryCheckout(path: .init(id: "e"))
        #expect(try response.conflict.body.json.error.code == "TOURNAMENT_PAYMENT_NOT_DUE")
    }
}

